package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="society_daily_reports",uniqueConstraints=@UniqueConstraint(name="uk_society_daily_report_account_date",columnNames={"account_id","report_date"})) @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyDailyReport {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @Column(nullable=false) private LocalDate reportDate; @Column(nullable=false) private Integer revision; @Column(nullable=false,length=20) @Builder.Default private String status="DRAFT"; @Column(length=4000) private String summary; @Column(length=2000) private String nextDayPriorities; @Column(nullable=false,columnDefinition="TEXT") private String snapshotJson; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="submitted_by_user_id") private User submittedBy; private LocalDateTime submittedAt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="acknowledged_by_user_id") private User acknowledgedBy; private LocalDateTime acknowledgedAt; @Column(length=2000) private String adminComment; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();}}
